import {toMicrogold,fromMicrogold,addMicrogold} from './money.js?v=babbc3d3950e';
// Accounting telemetry only. Transactions and sailing remain engine-owned.
export class VoyageJournal {
 constructor(){this.history=[];this.current=null;this.completed=0;this.realisedProfit=0;this.realisedProfitUnits=0;}
 begin(origin,destination,tick,maintenance){if(this.current){this.current.destination=destination;return;}this.current={origin,destination,startTick:tick,maintenanceStart:maintenance,purchaseUnits:0,revenueUnits:0,purchases:0,revenue:0,cargo:{}};}
 plan(details){if(this.current){this.current.tradeDebug??={plans:[],transactions:[]};const plans=this.current.tradeDebug.plans;plans.push(structuredClone(details));if(plans.length>20)plans.shift();}}
 lock(details){if(this.current){this.current.tradeDebug??={plans:[],transactions:[]};this.current.tradeDebug.purchaseLock=structuredClone(details);}}
 transaction(kind,commodity,quantity,gold,tick,port){if(!this.current)return;this.current.tradeDebug??={plans:[],transactions:[]};const list=this.current.tradeDebug.transactions;let row=list.find(r=>r.kind===kind&&r.commodity===commodity&&r.port===port);if(!row){row={kind,commodity,port,firstTick:tick,lastTick:tick,batches:0,quantity:0,gold:0,minUnitPrice:Infinity,maxUnitPrice:0};list.push(row);}const price=gold/quantity;row.lastTick=tick;row.batches++;row.quantity+=quantity;row.goldUnits=addMicrogold(row.goldUnits??0,toMicrogold(gold));row.gold=fromMicrogold(row.goldUnits);row.minUnitPrice=Math.min(row.minUnitPrice,price);row.maxUnitPrice=Math.max(row.maxUnitPrice,price);row.averageUnitPrice=row.gold/row.quantity;}
 purchase(commodity,quantity,gold,tick=null,port=null){if(!this.current)return;const c=this.current.cargo[commodity]??={loaded:0,delivered:0};c.loaded+=quantity;this.current.purchaseUnits=addMicrogold(this.current.purchaseUnits,toMicrogold(gold));this.current.purchases=fromMicrogold(this.current.purchaseUnits);this.transaction('BUY',commodity,quantity,gold,tick,port);}
 sell(commodity,quantity,gold,tick=null,port=null){if(!this.current)return;const c=this.current.cargo[commodity]??={loaded:0,delivered:0};c.delivered+=quantity;this.current.revenueUnits=addMicrogold(this.current.revenueUnits,toMicrogold(gold));this.current.revenue=fromMicrogold(this.current.revenueUnits);this.transaction('SELL',commodity,quantity,gold,tick,port);}
 purchaseAccepted(c,q,g,t,p){this.purchase(c,q,g,t,p);const row=this.current?.cargo[c];if(row){row.loaded-=q;row.purchased=(row.purchased??0)+q;}}
 saleAccepted(c,q,g,t,p,acquisitionCost=0){this.sell(c,q,g,t,p);const row=this.current?.cargo[c];if(row){row.delivered-=q;row.sold=(row.sold??0)+q;row.soldAcquisitionCostUnits=addMicrogold(row.soldAcquisitionCostUnits??0,toMicrogold(acquisitionCost));row.soldAcquisitionCost=fromMicrogold(row.soldAcquisitionCostUnits);this.current.soldAcquisitionCostUnits=addMicrogold(this.current.soldAcquisitionCostUnits??0,toMicrogold(acquisitionCost));this.current.soldAcquisitionCost=fromMicrogold(this.current.soldAcquisitionCostUnits);}}
 handled(kind,c,q){if(!this.current)return;const row=this.current.cargo[c]??={loaded:0,delivered:0};row[kind==='PICKUP'?'loaded':'delivered']+=q;}
 loss(c,q,cost,tick,reason='dumping'){if(!this.current)return;const row=this.current.cargo[c]??={loaded:0,delivered:0};row.lost=(row.lost??0)+q;row.lostAcquisitionCostUnits=addMicrogold(row.lostAcquisitionCostUnits??0,toMicrogold(cost));row.lostAcquisitionCost=fromMicrogold(row.lostAcquisitionCostUnits);this.current.losses??=[];this.current.losses.push({commodity:c,quantity:q,acquisitionCostUnits:toMicrogold(cost),acquisitionCost:cost,tick,reason});if(this.current.losses.length>100)this.current.losses.shift();}
 complete(destination,tick,maintenance){if(!this.current)return;const v=this.current;v.destination=destination;v.endTick=tick;v.maintenanceUnits=Math.max(0,toMicrogold(maintenance)-toMicrogold(v.maintenanceStart));v.maintenance=fromMicrogold(v.maintenanceUnits);v.profitUnits=v.revenueUnits-v.purchaseUnits-v.maintenanceUnits;v.profit=v.profitUnits/1e6;delete v.maintenanceStart;this.realisedProfitUnits=(this.realisedProfitUnits??0)+v.profitUnits;if(!Number.isSafeInteger(this.realisedProfitUnits))throw RangeError('Profit overflow');this.realisedProfit=this.realisedProfitUnits/1e6;this.completed++;this.history.unshift(v);if(this.history.length>100)this.history.pop();this.current=null;}
 snapshot(){return structuredClone({history:this.history,current:this.current,completed:this.completed,realisedProfitUnits:this.realisedProfitUnits,realisedProfit:this.realisedProfit});}
}
